"""Glossary lookup for Universal Software Generation Engines."""

GLOSSARY = {
    "world model": "an internal predictive representation of an environment or domain used to forecast outcomes",
    "guardrail": "a hard constraint or check that blocks unsafe or out-of-scope actions",
    "provenance chain": "the recorded history of where each piece of data and each decision came from",
    "evaluation harness": "a repeatable battery of tests measuring capability, safety, and regressions",
    "capability envelope": "the documented range of tasks the system is proven to handle",
    "hypothesis engine": "a component that formulates testable explanations from observations",
}

def lookup(term):
    key = term.strip().lower()
    for k, v in GLOSSARY.items():
        if k.lower() == key:
            return k + ": " + v
    cands = [k for k in GLOSSARY if key in k.lower()]
    return ("Did you mean: " + ", ".join(cands)) if cands else "No entry."


if __name__ == "__main__":
    print("Universal Software Generation Engines glossary — %d terms" % len(GLOSSARY))
    for t in list(GLOSSARY)[:3]:
        print("-", lookup(t))

"""Piece model: Knowledge Ingestion Layer — part of the Universal Software Generation Engines system."""
import random

class UniversalSoftwareGenerationEnginesPiece1KnowledgeIngestion:
    """Models the Knowledge Ingestion Layer piece: specification check and behavior sample."""

    SPEC = {"piece": "Knowledge Ingestion Layer", "interfaces": 3, "redundancy": 2}

    def __init__(self, seed=11):
        self.rng = random.Random(seed)

    def spec_check(self):
        """Verify the piece meets its interface contract."""
        results = {}
        for i in range(self.SPEC["interfaces"]):
            # simulated conformance measurement around a nominal value
            measured = 1.0 + self.rng.uniform(-0.04, 0.04)
            results["interface_%d" % i] = round(measured, 3)
        ok = all(0.94 <= v <= 1.06 for v in results.values())
        return {"pass": ok, "measurements": results}

    def simulate(self, cycles=24):
        """Sample operating behavior over a number of cycles."""
        health = 1.0
        for _ in range(cycles):
            stress = self.rng.uniform(0.0, 0.06)
            health = max(0.0, health - stress * 0.2)
            health = min(1.0, health + 0.05)  # recovery / maintenance
        return {"cycles": cycles, "health": round(health, 3),
                "redundancy_ok": health > 0.5}


if __name__ == "__main__":
    m = UniversalSoftwareGenerationEnginesPiece1KnowledgeIngestion(seed=11)
    sc = m.spec_check()
    sm = m.simulate(24)
    print("Knowledge Ingestion Layer — Universal Software Generation Engines")
    print("spec check pass:", sc["pass"], "| measurements:", sc["measurements"])
    print("health after", sm["cycles"], "cycles:", sm["health"])

